#!/usr/bin/env python3
"""Full host reachability test."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler
import re

HOSTS = {
    "B1-PC1": {"host":"192.168.122.31","lab_ip":"10.1.1.10","guest":False},
    "B1-PC2": {"host":"192.168.122.32","lab_ip":"10.1.1.11","guest":False},
    "B2-PC1": {"host":"192.168.122.33","lab_ip":"10.1.2.10","guest":False},
    "B2-PC2": {"host":"192.168.122.34","lab_ip":"10.1.2.11","guest":False},
    "B3-PC1": {"host":"192.168.122.35","lab_ip":"10.1.3.10","guest":False},
    "B3-PC2": {"host":"192.168.122.36","lab_ip":"10.1.3.11","guest":False},
    "B4-PC1": {"host":"192.168.122.37","lab_ip":"10.2.1.10","guest":False},
    "B4-PC2": {"host":"192.168.122.38","lab_ip":"10.2.1.11","guest":False},
    "B4-PC3": {"host":"192.168.122.39","lab_ip":"10.2.2.10","guest":True},
    "B4-PC4": {"host":"192.168.122.40","lab_ip":"10.2.2.11","guest":True},
}

INTERNET_TARGETS = ["8.8.8.8", "1.1.1.1"]

def ping_from(src_name, src_info, targets):
    """Ping a list of target IPs from a host. Returns dict of target->result."""
    results = {}
    try:
        conn = ConnectHandler(device_type="linux", host=src_info["host"],
                            username="root", password="alpine", timeout=15)
        for tgt_ip in targets:
            out = conn.send_command(f"ping -c 2 -W 3 {tgt_ip}", read_timeout=15)
            loss = re.search(r'(\d+)% packet loss', out)
            results[tgt_ip] = "OK" if loss and int(loss.group(1)) == 0 else "FAIL"
        conn.disconnect()
    except Exception as e:
        for tgt_ip in targets:
            results[tgt_ip] = f"ERR:{e}"
    return src_name, results

# Build test matrix
all_lab_ips = {name: info["lab_ip"] for name, info in HOSTS.items()}
tasks = []
for src_name, src_info in HOSTS.items():
    targets = []
    for tgt_name, tgt_info in HOSTS.items():
        if tgt_name != src_name:
            targets.append(tgt_info["lab_ip"])
    targets.extend(INTERNET_TARGETS)
    tasks.append((src_name, src_info, targets))

results = {}
with ThreadPoolExecutor(max_workers=10) as pool:
    futs = {pool.submit(ping_from, t[0], t[1], t[2]): t[0] for t in tasks}
    for f in as_completed(futs):
        name, res = f.result()
        results[name] = res
        print(f"  done: {name}")

# Analyze results
non_guest = [n for n,i in HOSTS.items() if not i["guest"]]
guest = [n for n,i in HOSTS.items() if i["guest"]]

print("\n=== NON-GUEST TO NON-GUEST (should all pass) ===")
ng_pass = 0; ng_fail = 0
for src in non_guest:
    for tgt in non_guest:
        if src == tgt: continue
        tgt_ip = HOSTS[tgt]["lab_ip"]
        r = results.get(src, {}).get(tgt_ip, "MISSING")
        if r == "OK":
            ng_pass += 1
        else:
            ng_fail += 1
            print(f"  FAIL: {src} -> {tgt} ({tgt_ip}): {r}")
print(f"  Total: {ng_pass} pass, {ng_fail} fail")

print("\n=== GUEST TO GUEST (should pass) ===")
for src in guest:
    for tgt in guest:
        if src == tgt: continue
        tgt_ip = HOSTS[tgt]["lab_ip"]
        r = results.get(src, {}).get(tgt_ip, "MISSING")
        print(f"  {src} -> {tgt}: {r}")

print("\n=== GUEST <-> NON-GUEST (should all fail) ===")
gng_pass = 0; gng_fail = 0
for src in guest:
    for tgt in non_guest:
        tgt_ip = HOSTS[tgt]["lab_ip"]
        r = results.get(src, {}).get(tgt_ip, "MISSING")
        if r == "FAIL":
            gng_pass += 1
        else:
            gng_fail += 1
            print(f"  UNEXPECTED PASS: {src} -> {tgt} ({tgt_ip})")
for src in non_guest:
    for tgt in guest:
        tgt_ip = HOSTS[tgt]["lab_ip"]
        r = results.get(src, {}).get(tgt_ip, "MISSING")
        if r == "FAIL":
            gng_pass += 1
        else:
            gng_fail += 1
            print(f"  UNEXPECTED PASS: {src} -> {tgt} ({tgt_ip})")

print(f"  Total: {gng_pass} correctly blocked, {gng_fail} unexpected passes")

print("\n=== INTERNET REACHABILITY (all hosts should reach 8.8.8.8 and 1.1.1.1) ===")
for src_name in sorted(HOSTS.keys()):
    for tgt in INTERNET_TARGETS:
        r = results.get(src_name, {}).get(tgt, "MISSING")
        if r != "OK":
            print(f"  FAIL: {src_name} -> {tgt}: {r}")
        else:
            print(f"  OK: {src_name} -> {tgt}")
